package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.Zero
var WsTotal decimal.Decimal = decimal.Zero
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var loanRec LoanRec
var loanRecords []string
var loanIndex int
var outputWriter *bufio.Writer

func parseDecimalField(s string, scale int32) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	var b strings.Builder
	for _, r := range t {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		} else if r == ' ' {
			b.WriteRune('0')
		}
	}
	ds := b.String()
	if ds == "" {
		return decimal.Zero
	}
	d, err := decimal.NewFromString(ds)
	if err != nil {
		return decimal.Zero
	}
	return d.Shift(-scale)
}

func parseIntField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	var b strings.Builder
	for _, r := range t {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		} else if r == '-' {
			b.WriteRune(r)
		}
	}
	ds := b.String()
	if ds == "" || ds == "-" {
		return 0
	}
	v, err := strconv.ParseInt(ds, 10, 64)
	if err != nil {
		return 0
	}
	return v
}

func roundHalfAway(v decimal.Decimal, scale int32) decimal.Decimal {
	scaled := v.Shift(scale)
	t := scaled.Truncate(0)
	diff := scaled.Sub(t)
	absDiff := diff.Abs()
	half := decimal.NewFromInt(1).Shift(-1) // 0.5
	if absDiff.Cmp(half) >= 0 {
		if v.Sign() >= 0 {
			t = t.Add(decimal.NewFromInt(1))
		} else {
			t = t.Sub(decimal.NewFromInt(1))
		}
	}
	return t.Shift(-scale)
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	var scaled decimal.Decimal
	if rounded {
		scaled = roundHalfAway(v, scale)
	} else {
		scaled = v.Truncate(scale)
	}
	sign := scaled.Sign()
	abs := scaled
	if sign < 0 {
		abs = abs.Neg()
	}
	s := abs.StringFixed(scale)
	var intStr, fracStr string
	if scale == 0 {
		intStr = s
		intStr = strings.TrimPrefix(intStr, "-")
		intStr = strings.TrimPrefix(intStr, "+")
		fracStr = ""
	} else {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		intStr = strings.TrimPrefix(intStr, "-")
		intStr = strings.TrimPrefix(intStr, "+")
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", int(scale))
		}
		if len(fracStr) < int(scale) {
			fracStr += strings.Repeat("0", int(scale)-len(fracStr))
		} else if len(fracStr) > int(scale) {
			fracStr = fracStr[:scale]
		}
	}
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	if intStr == "" {
		intStr = "0"
	}
	var recon string
	if scale == 0 {
		recon = intStr
	} else {
		recon = intStr + "." + fracStr
	}
	d2, _ := decimal.NewFromString(recon)
	if sign < 0 && !d2.IsZero() {
		d2 = d2.Neg()
	}
	return d2
}

func storeInt(val int64, digits int) int64 {
	var mod int64 = 1
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if val >= 0 {
		return val % mod
	}
	return -((-val) % mod)
}

func formatEdited(value decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var picInt, picFrac string
	if dotIdx >= 0 {
		picInt = picture[:dotIdx]
		picFrac = picture[dotIdx+1:]
	} else {
		picInt = picture
		picFrac = ""
	}
	N := 0
	for _, ch := range picInt {
		if ch == 'Z' || ch == '9' {
			N++
		}
	}
	M := 0
	for _, ch := range picFrac {
		if ch == 'Z' || ch == '9' {
			M++
		}
	}
	absVal := value
	if value.Sign() < 0 {
		absVal = absVal.Neg()
	}
	var intStr, fracStr string
	if M > 0 {
		s := absVal.StringFixed(int32(M))
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", M)
		}
		intStr = strings.TrimPrefix(intStr, "-")
		intStr = strings.TrimPrefix(intStr, "+")
		if len(fracStr) < M {
			fracStr += strings.Repeat("0", M-len(fracStr))
		} else if len(fracStr) > M {
			fracStr = fracStr[:M]
		}
	} else {
		s := absVal.StringFixed(0)
		if strings.Contains(s, ".") {
			parts := strings.SplitN(s, ".", 2)
			intStr = parts[0]
		} else {
			intStr = s
		}
		intStr = strings.TrimPrefix(intStr, "-")
		intStr = strings.TrimPrefix(intStr, "+")
		fracStr = ""
	}
	if len(intStr) > N {
		intStr = intStr[len(intStr)-N:]
	}
	if len(intStr) < N {
		intStr = strings.Repeat("0", N-len(intStr)) + intStr
	}
	type slotInfo struct {
		pos   int
		isZ   bool
		digit byte
		disp  byte
	}
	var slots []slotInfo
	outInt := make([]byte, len(picInt))
	digPos := 0
	for i := 0; i < len(picInt); i++ {
		ch := picInt[i]
		if ch == 'Z' || ch == '9' {
			d := intStr[digPos]
			isZ := ch == 'Z'
			slots = append(slots, slotInfo{pos: i, isZ: isZ, digit: d})
			outInt[i] = '?'
			digPos++
		} else if ch == ',' {
			outInt[i] = ','
		} else {
			outInt[i] = byte(ch)
		}
	}
	significant := false
	for idx := range slots {
		d := slots[idx].digit
		isZ := slots[idx].isZ
		if d != '0' {
			slots[idx].disp = d
			significant = true
		} else {
			if significant {
				slots[idx].disp = '0'
			} else {
				if isZ {
					slots[idx].disp = ' '
				} else {
					slots[idx].disp = '0'
					significant = true
				}
			}
		}
	}
	for _, sl := range slots {
		outInt[sl.pos] = sl.disp
	}
	for i := 0; i < len(picInt); i++ {
		if picInt[i] == ',' {
			leftSignificant := false
			for _, sl := range slots {
				if sl.pos < i && sl.disp != ' ' {
					leftSignificant = true
					break
				}
			}
			if leftSignificant {
				outInt[i] = ','
			} else {
				outInt[i] = ' '
			}
		}
	}
	intPartStr := string(outInt)
	if M > 0 {
		return intPartStr + "." + fracStr
	}
	return intPartStr
}

func formatUneditedInt(v int64, width int) string {
	if v < 0 {
		v = -v
	}
	s := strconv.FormatInt(v, 10)
	if len(s) > width {
		s = s[len(s)-width:]
	} else if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func ReadPara() {
	if loanIndex >= len(loanRecords) {
		WsEofFlag = "Y"
		return
	}
	line := loanRecords[loanIndex]
	loanIndex++
	if len(line) < 21 {
		line += strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	acctRaw := line[0:6]
	prinRaw := line[6:15]
	rateRaw := line[15:19]
	yearsRaw := line[19:21]
	loanRec.LrAcct = acctRaw
	loanRec.LrPrincipal = parseDecimalField(prinRaw, 2)
	loanRec.LrRate = parseDecimalField(rateRaw, 2)
	loanRec.LrYears = parseIntField(yearsRaw)
}

func ProcessPara() {
	yearsDec := decimal.NewFromInt(loanRec.LrYears)
	raw := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(yearsDec).Shift(-2)
	WsInterest = storeDecimal(raw, 9, 2, true)
	WsTotal = storeDecimal(WsTotal.Add(WsInterest), 11, 2, false)
	WsCount = storeInt(WsCount+1, 5)
	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	line := loanRec.LrAcct + " " + WsPrinEd + " " + WsIntEd
	outputWriter.WriteString(line + "\n")
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsCount, 5)
	outputWriter.WriteString("RECORDS: " + countStr + "\n")
	outputWriter.WriteString("TOTAL INTEREST: " + WsTotalEd + "\n")
}

func MainPara() {
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func main() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to open input.dat: %v\n", err)
		os.Exit(1)
	}
	content := string(data)
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "\n")
	if len(content) == 0 {
		loanRecords = []string{}
	} else {
		lines := strings.Split(content, "\n")
		if strings.HasSuffix(content, "\n") {
			if len(lines) > 0 && lines[len(lines)-1] == "" {
				lines = lines[:len(lines)-1]
			}
		}
		loanRecords = lines
	}
	loanIndex = 0
	WsEofFlag = "N"
	WsInterest = decimal.Zero
	WsTotal = decimal.Zero
	WsCount = 0
	outputWriter = bufio.NewWriter(os.Stdout)
	defer outputWriter.Flush()
	MainPara()
	outputWriter.Flush()
}

